2637	 */
2638	static inline
2639	unsigned long plain_advance_to_6kp1(uint64_t *lsb, unsigned long count,
2640	                          struct PP_Mod16bit *ps,
2641		                 struct SIMD_Advance *adv)
2642	{
2643		static unsigned long rv = 0;
2644	
2645		if (ps && adv && (ps->mod6 == 5)) {         // advance 6k+5 -> 6(k+1)+1
