774	/*-----------------------------------------
775	 * 'plain' prime search: can modn[] indicate a prime?
776	 *
777	 * SECURITY NOTE: tmp[] and tmp2[] are scratch, filled with (potentially)secret
778	 * state-dependent data, and SHOULD be wiped upon return.
779	 */
780	static inline
781	REALLY_FORCE_INLINE
782	/**/
783	uint16_t simd_nofactor64x16(uint16_t tmp[static 64],
784	                           uint16_t tmp2[static 64],
785	                     const uint16_t modn[static 64],
786	                      const uint16_t inv[static 64],
787	                    const uint16_t limit[static 64])
788	{
789						// compute n * 1/prime  mod 2^16
790	
791		simd_mul16x16(  tmp,          modn,          inv       );
792		simd_mul16x16(&(tmp[ 16 ]), &(modn[ 16 ]), &(inv[ 16 ]));
793		simd_mul16x16(&(tmp[ 32 ]), &(modn[ 32 ]), &(inv[ 32 ]));
794		simd_mul16x16(&(tmp[ 48 ]), &(modn[ 48 ]), &(inv[ 48 ]));
795	
796						// any of the products <= limit[ ]?
797						// divides -> ffff; not -> 0
798	
799		simd_lemask16x16_inpl(  tmp,          limit       );
800		simd_lemask16x16_inpl(&(tmp[ 16 ]), &(limit[ 16 ]));
801		simd_lemask16x16_inpl(&(tmp[ 32 ]), &(limit[ 32 ]));
802		simd_lemask16x16_inpl(&(tmp[ 48 ]), &(limit[ 48 ]));
803	
804		return simd_is_all0x64x16_inpl(tmp, tmp2);
805	}
