594	/*--------------------------------------
595	 * safe-prime comparison: with v[] storing x * mod small-primes[],
596	 * report if any of the P|x or P|2x+1: r[] will be all-00 if no factor
597	 *
598	 * since comparing to 0 is expected intrinsic, report 0 if dividing, >0 if not
599	 * 'v' is x * 1/prime
600	 *
601	 * 'r' is filled with 16x16-bit result
602	 *     ffff  entry divides x  OR  divides 2x+1
603	 *        0  divides none
604	 *
605	 * (1) A1 =  x * 1/prime   mod 2^16
606	 * (2) A1 <= B             <->  prime divides x
607	 *
608	 * (3) A2 = (2x + 1) * 1/prime  mod 2^16  ==
609	 *          (2 * A1 + 1/prime)  mod 2^16
610	 * (4) A2 <= B             <->  prime divides 2x+1
611	 *
612	 *------------------------------------*/
613	static inline
614	REALLY_FORCE_INLINE
615	//
616	void simd_spcmp16x16(uint16_t r[static 16], const uint16_t v[static 16],
617	             const uint16_t inv[static 16],
618	           const uint16_t limit[static 16])
619	{
620		uint16_t tmp[16];
621	// TODO: use external tmp[] which may be centrally wiped
622	
623		simd_shladd16x16(tmp, v, inv);                   // 2*v+inv[]  mod 2^16
624	
625		simd_min16x16(r, v, tmp);
626	
627		simd_lemask16x16_inpl(r, limit);           // divides -> ffff; not -> 0
628	}
