665	// note: zero-flag (ZF) checking for 256-bit wide SIMD units
666	// above, we rely on the all-0 16x16-bit representation 
667	//
668	// there are equivalent intrinsics, or even the straightforward AND-all
669	// of 16x16 bits may turn into a short construct. TBD
670	//
671	#if 0
672	#if (SYS__X86_BITS >= 64)
673		return _mm256_testz_si256((const __m256i) *v, (const __m256i) *v);
674			// 
675			// compare-all-0 compiles into vpxor, vptest "close enough"
676	
677	#elif (SYS__AARCH >= 64)
678		return (vmaxvq_u16(v) == 0);
679			// MAX(..16x16 bits..); does not require use of all-0
680			// aux. register
681			//
682			// compiles into:
683			//     umaxv hd,vn.8h   "Unsigned Maximum across Vector"
684			//
685			// see developer.arm.com/architectures/instruction-sets/
686			//     intrinsics/vmaxvq_u16
687	
688	#elif (SYS__S390_BITS >= 64)
689	#error "supply S390 check-ZF(compare-0) intrinsic here"
690	
691	#else
692		return !!((((v[  0 ] | v[  1 ]) | (v[  2 ] | v[  3 ]))  &
693		           ((v[  4 ] | v[  5 ]) | (v[  6 ] | v[  7 ]))) &
694		          (((v[  8 ] | v[  9 ]) | (v[ 10 ] | v[ 11 ]))  &
695		           ((v[ 12 ] | v[ 13 ]) | (v[ 14 ] | v[ 15 ]))));
696			// note the 8x2 split
697			// expect to be specialized into faster-than-16x expression
698	
699	#endif
700	#endif
701	#endif       // /256 bits
