704	/*-----------------------------------------
705	 * is 64x16 wide SIMD array all zeroes?
706	 *
707	 * SECURITY NOTE: tmp[] is scratch which caller MUST wipe
708	 * NOTE: DESTROYS ORIGINAL INPUTS
709	 */
710	static inline
711	REALLY_FORCE_INLINE
712	/**/
713	unsigned int simd_is_all0x64x16_inpl(uint16_t v[static 64],
714	                                   uint16_t tmp[static 16])
715	{
716		simd_or16x16(tmp, &(v[32]), &(v[48]));       // 2 3
717		simd_or16x16(v,     v,      &(v[16]));       // 0 1
718		simd_or16x16(v,     tmp,      v     );       // 0 1 2 3
719	
720		return simd_is_all0(v);
721	}
722	
