724	/*-----------------------------------------
725	 * v[] += adv; preserving mod-prime by subtracting m2r[] if applicable
726	 */
727	static inline
728	REALLY_FORCE_INLINE
729	/**/
730	void simd_advance64x16_m2r_inpl(uint16_t v[static 64], uint16_t adv,
731	                        const uint16_t m2r[static 64])
732	{
733		simd_advance16x16_inpl(  v,          adv       );
734		simd_m2range16x16_inpl(  v,          m2r       );
735	
736		simd_advance16x16_inpl(&(v[ 16 ]),   adv       );
737		simd_m2range16x16_inpl(&(v[ 16 ]), &(m2r[ 16 ]));
738	
739		simd_advance16x16_inpl(&(v[ 32 ]),   adv       );
740		simd_m2range16x16_inpl(&(v[ 32 ]), &(m2r[ 32 ]));
741	
742		simd_advance16x16_inpl(&(v[ 48 ]),   adv       );
743		simd_m2range16x16_inpl(&(v[ 48 ]), &(m2r[ 48 ]));
744	}
