808	/*--------------------------------------
809	 * does the first set of prime moduli (64 primes) indicate prime?
810	 *
811	 * SECURITY NOTE: tmp[] and tmp2[] are scratch areas, which caller
812	 * MUST maintain and wipe
813	 */
814	static inline
815	REALLY_FORCE_INLINE
816	/**/
817	uint16_t simd_nofactor_first(uint16_t tmp[static 64],
818	                             uint16_t tm2[static 64],
819	             const struct PP_Mod16bit *ps)
820	{
821		return simd_nofactor64x16(tmp, tm2, ps->modn,
822		                          firstprimes_inverse_simd,
823		                          firstprimes_mullimit_simd);
824	}
