494	 * assume aggressive+forced inlining leads to recognized specialization
495	 * for src==dest; we do not replicate the simd_m2range16x16() fn. body
496	 * here
497	 */
498	static inline
499	REALLY_FORCE_INLINE
500	//
501	void simd_m2range16x16_inpl(uint16_t v[static 16],
502	                    const uint16_t m2r[static 16])
503	{
504		simd_m2range16x16(v, v, m2r);
505	}
